import unittest
from candidate import count_distinct_characters

class TestCountDistinctCharacters(unittest.TestCase):
    def test_normal_case_uppercase(self):
        self.assertEqual(count_distinct_characters('ABCABC'), 3)

    def test_normal_case_lowercase(self):
        self.assertEqual(count_distinct_characters('abcabc'), 3)

    def test_normal_case_mixed_case(self):
        self.assertEqual(count_distinct_characters('aBcAbC'), 3)

    def test_normal_case_with_numbers(self):
        self.assertEqual(count_distinct_characters('a1b2c3'), 3)

    def test_normal_case_with_special_chars(self):
        self.assertEqual(count_distinct_characters('a@b#c$'), 3)

    def test_empty_string(self):
        self.assertEqual(count_distinct_characters(''), 0)

    def test_single_character(self):
        self.assertEqual(count_distinct_characters('a'), 1)

    def test_all_same_characters(self):
        self.assertEqual(count_distinct_characters('aaaa'), 1)

    def test_case_insensitive_duplicate_removal(self):
        self.assertEqual(count_distinct_characters('AaBbCc'), 3)

    def test_boundary_case_minimum_length(self):
        self.assertEqual(count_distinct_characters('x'), 1)

    def test_boundary_case_maximum_length(self):
        self.assertEqual(count_distinct_characters('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'), 52)

    def test_none_input(self):
        with self.assertRaises(TypeError):
            count_distinct_characters(None)

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            count_distinct_characters(123)

    def test_string_with_unicode_chars(self):
        self.assertEqual(count_distinct_characters('café naïve'), 4)

    def test_string_with_spaces(self):
        self.assertEqual(count_distinct_characters('hello world'), 8)

    def test_string_with_tabs_and_newlines(self):
        self.assertEqual(count_distinct_characters('a\tb\nc'), 3)

    def test_string_with_only_spaces(self):
        self.assertEqual(count_distinct_characters('   '), 1)

    def test_string_with_whitespace_and_letters(self):
        self.assertEqual(count_distinct_characters('  a b c  '), 3)
